'use client';

import * as React from 'react';
import {createComponent} from '@lit/react';
import '@material/web/labs/gb/components/badge/md-gb-badge.js';
import {BadgeElement} from '@material/web/labs/gb/components/badge/badge-element.js';

/**
 * A Material Design badge component. Wraps <md-gb-badge>.
 * Docs: https://material-web.dev/3.0/components/badge/
 */
export const MdBadge = createComponent({
  react: React,
  tagName: 'md-gb-badge',
  elementClass: BadgeElement,
});

export type MdBadgeProps = React.ComponentProps<typeof MdBadge>;
